import math
from contextlib import contextmanager

def log_decorator(func):
    def wrapper(*args, **kwargs):
        result = func(*args, **kwargs)
        return result
    return wrapper

class StateMachine:
    def __init__(self):
        self.state = 'IDLE'

    @log_decorator
    def process(self, input_signal):
        if self.state == 'IDLE' and input_signal > 0:
            self.state = 'ACTIVE'
            return 1
        elif self.state == 'ACTIVE':
            if input_signal == 0:
                self.state = 'LATCHED'
                return 2
            else:
                return (input_signal ** 2) % 7
        elif self.state == 'LATCHED':
            if input_signal < 0:
                self.state = 'ERROR'
                return -1
            else:
                return int(math.log(input_signal + 1)) if input_signal > 0 else 0
        else:  # ERROR state
            return 0

@contextmanager
def circuit_context():
    sm = StateMachine()
    try:
        yield sm
    finally:
        pass

