def transform_and_hash(transform_func):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            transformed = transform_func(args[0])
            hashed = hashlib.md5(transformed.encode()).hexdigest()
            return func(hashed, *args[1:], **kwargs)
        return wrapper
    return decorator

